Raw Scraping Scripts
Here, we attach the raw scraping scripts for the company 10Qs including the scripts for R&D values and the Item 2 section of each report for text analysis.


10Q R&D Numbers
Main student who worked on this: Alisha

# Student that worked on this section: Alisha
# -----------------------------------------------------------------------------
# This is the code for scraping 10-Q R&D expenses from the SEC website's HTML 
# files for Microsoft, Google, Meta, Apple, Nvidia, and Tesla
# -----------------------------------------------------------------------------

# packages
library(tidyverse)
library(rvest)
library(robotstxt)
library(httr)

# Import dataset 
# Variable Explanations:
# COMP: Company Name
# FIL-D: Filing Date
# REP-D: Reporting For Date
# HTML: HTML link

# find data in sibling folder
ten_Qs &lt;- readxl::read_xlsx("../data/10q-links.xlsx")

# Compartmentalize each variable
# Microsoft
microsoft &lt;- ten_Qs |&gt;
  filter(COMP == "Microsoft")

# Google
google &lt;- ten_Qs |&gt;
  filter(COMP == "Google")

# Meta
meta &lt;- ten_Qs |&gt;
  filter(COMP == "Meta")

# Apple
apple &lt;- ten_Qs |&gt;
  filter(COMP == "Apple")

# Nvidia
nvidia &lt;- ten_Qs |&gt;
  filter(COMP == "Nvidia")

# Tesla
tesla &lt;- ten_Qs |&gt;
  filter(COMP == "Tesla")

# Create SEC session
my_ua &lt;- "AmherstCollege alxu27@amherst.edu"
sec_session &lt;- session("https://www.sec.gov", user_agent(my_ua))

# Add empty column to store values
ten_Qs &lt;- ten_Qs |&gt;
  mutate(RD = NA)

# -------------------------------Scraping---------------------------------------
# Microsoft
for (i in 1:4) {
  ten_Qs$RD[i] &lt;- session_jump_to(sec_session, microsoft$HTML[i]) |&gt;
    read_html() |&gt;
    html_elements("table") |&gt;
    purrr::pluck(7) |&gt;
    html_table() |&gt;
    filter(X1 == "Research and development") |&gt;
    select(X4)
}

# Google
for (i in 1:2) {
  ten_Qs$RD[i+4] &lt;- session_jump_to(sec_session, google$HTML[i]) |&gt;
    read_html() |&gt;
    html_elements("table") |&gt;
    purrr::pluck(14) |&gt;
    html_table() |&gt;
    filter(X1 == "Research and development") |&gt;
    select(X10)
}

for (i in 1:2) {
  ten_Qs$RD[i+6] &lt;- session_jump_to(sec_session, google$HTML[i+2]) |&gt;
    read_html() |&gt;
    html_elements("table") |&gt;
    purrr::pluck(15) |&gt;
    html_table() |&gt;
    filter(X1 == "Research and development") |&gt;
    select(X10)
}  

# Meta
for (i in 1:4) {
  ten_Qs$RD[i+8] &lt;- session_jump_to(sec_session, meta$HTML[i]) |&gt;
    read_html() |&gt;
    html_elements("table") |&gt;
    purrr::pluck(7) |&gt;
    html_table() |&gt;
    filter(X1 == "Research and development") |&gt;
    select(X4)
}

# Meta third 10-Q
ten_Qs$RD[11] &lt;- session_jump_to(sec_session, meta$HTML[3]) |&gt;
  read_html() |&gt;
  html_elements("table") |&gt;
  purrr::pluck(7) |&gt;
  html_table() |&gt;
  filter(X1 == "Research and development") |&gt;
  select(X16)

# Apple
for (i in 1:4) {
  ten_Qs$RD[i+12] &lt;- session_jump_to(sec_session, apple$HTML[i]) |&gt;
    read_html() |&gt;
    html_elements("table") |&gt;
    purrr::pluck(13) |&gt;
    html_table() |&gt;
    filter(X1 == "Research and development") |&gt;
    select(X4)
}

# Nvidia
for (i in 1:4) {
  ten_Qs$RD[i+16] &lt;- session_jump_to(sec_session, nvidia$HTML[i]) |&gt;
    read_html() |&gt;
    html_elements("table") |&gt;
    purrr::pluck(8) |&gt;
    html_table() |&gt;
    filter(X1 == "Research and development") |&gt;
    select(X4)
}

# Tesla
for (i in 1:4) {
  ten_Qs$RD[i+20] &lt;- session_jump_to(sec_session, tesla$HTML[i]) |&gt;
    read_html() |&gt;
    html_elements("table") |&gt;
    purrr::pluck(11) |&gt;
    html_table() |&gt;
    filter(X1 == "Research and development") |&gt;
    select(X4)
}

ten_Qs_RD &lt;- ten_Qs |&gt;
  select(!HTML)

# convert RD column into numeric type column
ten_Qs_RD &lt;- ten_Qs_RD |&gt;
  mutate(
    RD_clean = str_remove_all(RD, "[$, ]"), 
    RD = as.numeric(RD_clean)) |&gt;
  select(!RD_clean)

# export
write_csv(ten_Qs_RD, "../data/scraped-10qs.csv")



